mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys, collections
BASE="http://localhost:8080"
tok=None
events=collections.Counter()
log=[]
def get_token():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(BASE+"/token",method="POST",data=b""))
            tok=json.load(r)["token"]; events["token"]+=1; return
        except urllib.error.HTTPError as e:
            handle_err(e,"/token")
def handle_err(e,path):
    body=e.read().decode(errors="replace")
    events[f"{e.code}"]+=1
    log.append((path,e.code,dict(e.headers),body[:300]))
    if e.code==429:
        ra=e.headers.get("Retry-After")
        try: w=float(ra)
        except: w=2
        time.sleep(w+0.1)
    else:
        time.sleep(0.5)
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: get_token()
        req=urllib.request.Request(BASE+path,headers={"Authorization":"Bearer "+tok})
        try:
            r=urllib.request.urlopen(req,timeout=30)
            raw=r.read()
            return 200,json.loads(raw)
        except urllib.error.HTTPError as e:
            if e.code==404 and path.startswith("/customers"):
                body=e.read().decode(errors="replace"); log.append((path,404,dict(e.headers),body)); return 404,body
            if e.code in (401,403): tok=None
            handle_err(e,path)
        except Exception as e:
            events[type(e).__name__]+=1; log.append((path,"exc",{},repr(e))); time.sleep(0.5)
    raise RuntimeError("gave up "+path)
pages={}
path="/orders?page=1"
while path:
    st,d=get(path)
    pages[d["page"]]=d
    print("page",d["page"],d["total_pages"],len(d["items"]),d["next"],file=sys.stderr)
    path=d["next"]
json.dump(pages,open("/tmp/recon/pages.json","w"))
ids=sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
cust={}
for c in ids:
    st,d=get("/customers/"+c)
    cust[c]={"status":st,"data":d}
json.dump(cust,open("/tmp/recon/customers.json","w"))
json.dump({"events":events,"log":log},open("/tmp/recon/log.json","w"),default=str)
print(events,file=sys.stderr)
EOF
cd /tmp/recon && python3 -I fetch.py 2>&1 | tail -40

